  select id, created_at, staff, supervisor, base_plu, base_description, base_material, base_qty, total_cut_qty, difference, status, material_doc_a, material_doc_b, weight_discrepancy_doc, keyed_in_by, keyed_in_at
  from data
  on conflict (id) do nothing
  returning id
)
insert into cc_entry_cuts (entry_id, position, plu, description, material, qty)
select d.id, c.position, c.plu, c.description, c.material, c.qty
from data d
join new_entries n on n.id = d.id
cross join lateral jsonb_to_recordset(d.cuts) as c (position int, plu text, description text, material text, qty numeric);

select (select count(*) from cc_entries) as entries, (select count(*) from cc_entry_cuts) as cut_lines;
